"""Compare the summary-table rows with the detailed sections of the findings file."""
import re
import subprocess
import sys

repo = sys.argv[1]
path = "docs/pipeline_review_findings.md"


def doc(ref):
    return subprocess.check_output(["git", "-C", repo, "show", f"{ref}:{path}"]).decode("utf-8")


def parse(text):
    rows, sections, current = {}, {}, None
    for line in text.splitlines():
        heading = re.match(r"#{1,4} +(.*)", line)
        if heading:
            m = re.match(r"([GHML]\d+)\b", heading.group(1))
            current = m.group(1) if m else None
        row = re.match(r"\| *([GHML]\d+)\b[^|]*\|(.*)\|\s*$", line)
        if row:
            cells = [c.strip() for c in row.group(2).split("|")]
            rows.setdefault(row.group(1), []).append((cells[0], cells[-1]))
        status = re.match(r"\*\*Status:\*\* *([^·]+)", line)
        if status and current:
            sections[current] = status.group(1).strip()
    return rows, sections


def word(status):
    return status.split()[0].upper() if status else ""


for ref in sys.argv[2:]:
    rows, sections = parse(doc(ref))
    print(f"=== {ref}: {len(rows)} table rows, {len(sections)} sections with a status")
    for key in sorted(set(rows) | set(sections), key=lambda k: (k[0], int(k[1:]))):
        entries, section = rows.get(key, []), sections.get(key)
        if len(entries) != 1 or section is None:
            print(f"  {key}: table rows={len(entries)}, section status={section!r}")
            continue
        table, note = entries[0]
        if word(table) != word(section):
            print(f"  MISMATCH {key}: table '{table}' | section '{section}' | note: {note}")
        elif "→ W" in note:
            print(f"  note still points to a workstream, {key}: '{table}' | {note}")

