"""Combine finding statuses from master and the open PR branches and count them."""
import re
import subprocess
import sys

repo = sys.argv[1]
PATH = "docs/pipeline_review_findings.md"


def doc(ref):
    return subprocess.check_output(["git", "-C", repo, "show", f"{ref}:{PATH}"]).decode("utf-8")


def sections(text):
    out, key = {}, None
    for line in text.splitlines():
        heading = re.match(r"#{1,4} +(.*)", line)
        if heading:
            m = re.match(r"([GHML]\d+)\b", heading.group(1))
            key = m.group(1) if m else None
            if key:
                assert key not in out, f"duplicate section {key}"
                out[key] = []
        elif key:
            out[key].append(line)
    return {k: "\n".join(v).strip() for k, v in out.items()}


