def _mixed_rows():
    """Two sensor types, three breaths; row 1 is invalid and from an unused group."""
    return pd.DataFrame(
        {
            "sensor_type": ["type_2", "type_2", "type_2", "type_1", "type_1", "type_2"],
            "breath_number": [2, 2, 1, 2, 1, 3],
            "study_group": ["L-RAD", "NOT_LC", "LC", "LC", "LC", "LC"],
            "aggregated_reason": ["VALID", "INVALID_x", "VALID", "VALID", "VALID", "VALID"],
        }
    )


def test_only_the_training_sensor_and_breath_are_selected():
    positions, excluded = select_estimation_rows(
        _mixed_rows(), sensor_types=["type_2"], breath_numbers=(2,)
    )
    # The invalid row of the unused group stays: it matches sensor and breath.
    assert positions.tolist() == [0, 1]
    assert excluded == {"other_sensor_type": 2, "other_breath": 2}


def test_several_breaths_can_be_selected_but_never_another_sensor_type():
    positions, excluded = select_estimation_rows(
        _mixed_rows(), sensor_types=["type_2"], breath_numbers=(1, 3)
    )
    assert positions.tolist() == [2, 5]
    assert excluded == {"other_sensor_type": 2, "other_breath": 2}


