def test_rows_without_a_selection_column_are_an_error(column):
    with pytest.raises(KeyError, match=column):
        select_estimation_rows(
            _mixed_rows().drop(columns=[column]), sensor_types=["type_2"], breath_numbers=(2,)
        )


