def _training_selection(feature_run: FeatureRun) -> tuple[list[str], tuple[int, ...] | None]:
    """Sensor type and breath(s) the feature run selected for training.

    Read from the feature run's frozen config, so a later change to the run
    config doesn't change what its models are scored on. ``None`` breaths means
    every breath was selected.
    """
    path = feature_run.feature_run_path / RESOLVED_FEATURE_CONFIG_NAME
    if not path.is_file():
        raise FileNotFoundError(f"Cannot tell what the models were trained on: {path} is missing")
    settings = (yaml.safe_load(path.read_text(encoding="utf-8")) or {}).get("feature_settings") or {}
    sensor_types = normalize_sensor_types(settings.get("sensor_type"))
    if not sensor_types:
        raise ValueError(f"{path}: feature_settings.sensor_type is not recorded")
    breaths = settings.get("breath_number")
    if breaths is None:
        return sensor_types, None
    values = breaths if isinstance(breaths, list) else [breaths]
    return sensor_types, tuple(int(value) for value in values)


def select_estimation_rows(
    rows: pd.DataFrame,
    *,
    sensor_types: Sequence[str],
    breath_numbers: Sequence[int] | None,
) -> tuple[np.ndarray, dict[str, int]]:
    """Positions of the rows to score, and how many rows each filter left out.

    Only ``sensor_type`` and ``breath_number`` decide; study group and validity
    don't. ``breath_numbers=None`` keeps every breath.
    """
    missing = [column for column in ("sensor_type", "breath_number") if column not in rows.columns]
    if missing:
        raise KeyError(f"estimation rows are missing selection columns: {missing}")
    sensor = rows["sensor_type"].isin(list(sensor_types)).to_numpy()
    if breath_numbers is None:
        breath = np.ones(len(rows), dtype=bool)
    else:
        breath = pd.to_numeric(rows["breath_number"], errors="coerce").isin(list(breath_numbers)).to_numpy()
    excluded = {
        "other_sensor_type": int((~sensor).sum()),
        "other_breath": int((sensor & ~breath).sum()),
    }
    return np.flatnonzero(sensor & breath), excluded


